  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	let cachedLogicalPos: Point | null = null;
 13	let cachedScaleFactor: number | null = null;
 14	let cacheGeneration = 0;
 15	let pendingPositionRead: Promise<Point | null> | null = null;
 16	let trackingStarted = false;
 17	let pendingTracking: Promise<void> | null = null;
 18	
 19	function copyPoint(pos: Point): Point {
 20	  return { x: pos.x, y: pos.y };
 21	}
 22	
 23	function startPositionTracking(): void {
 24	  if (trackingStarted || pendingTracking) return;
 25	  const movedRegistration = win.onMoved(({ payload }) => {
 26	    cacheGeneration += 1;
 27	    if (cachedScaleFactor === null) {
 28	      cachedLogicalPos = null;
 29	      return;
 30	    }
 31	    cachedLogicalPos = { x: payload.x / cachedScaleFactor, y: payload.y / cachedScaleFactor };
 32	  });
 33	  const scaleRegistration = win.onScaleChanged(({ payload }) => {
 34	    cacheGeneration += 1;
 35	    cachedScaleFactor = payload.scaleFactor;
 36	    cachedLogicalPos = null;
 37	  });
 38	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
 39	    .then(([moved, scale]) => {
 40	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
 41	        trackingStarted = true;
 42	        return;
 43	      }
 44	      if (moved.status === "fulfilled") moved.value();
 45	      if (scale.status === "fulfilled") scale.value();
 46	    })
 47	    .finally(() => {
 48	      pendingTracking = null;
 49	    });
 50	}
 51	
 52	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 53	/// window or scaleFactor can't be read (e.g. window closing).
 54	export async function currentLogicalPos(): Promise<Point | null> {
 55	  startPositionTracking();
 56	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 57	  if (!pendingPositionRead) {
 58	    const generationAtReadStart = cacheGeneration;
 59	    pendingPositionRead = (async () => {
 60	      try {
 61	        const sf = await win.scaleFactor();
 62	        const p = await win.outerPosition();
 63	        if (generationAtReadStart !== cacheGeneration) {
 64	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
 65	        }
 66	        cachedScaleFactor = sf;
 67	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
 68	        return copyPoint(cachedLogicalPos);
 69	      } catch {
 70	        return null;
 71	      } finally {
 72	        pendingPositionRead = null;
 73	      }
 74	    })();
 75	  }
 76	  const pos = await pendingPositionRead;
 77	  return pos ? copyPoint(pos) : null;
 78	}
 79	
 80	/// Move the window to a logical-pixel position. Caller is responsible for
 81	/// clamping to the work area first.
 82	export async function setLogical(pos: Point): Promise<void> {
 83	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
 84	  cacheGeneration += 1;
 85	  cachedLogicalPos = copyPoint(pos);
 86	}
  1	import { beforeEach, describe, expect, it, vi } from "vitest";
  2	
  3	const nativeWindow = vi.hoisted(() => ({
  4	  scaleFactor: vi.fn(),
  5	  outerPosition: vi.fn(),
  6	  setPosition: vi.fn(),
  7	  onMoved: vi.fn(),
  8	  onScaleChanged: vi.fn(),
  9	}));
 10	
 11	vi.mock("@tauri-apps/api/window", () => ({
 12	  getCurrentWindow: () => nativeWindow,
 13	}));
 14	
 15	vi.mock("@tauri-apps/api/dpi", () => ({
 16	  LogicalPosition: class {
 17	    constructor(readonly x: number, readonly y: number) {}
 18	  },
 19	}));
 20	
 21	function deferred<T>() {
 22	  let resolve: (value: T) => void;
 23	  const promise = new Promise<T>((r) => { resolve = r; });
 24	  return { promise, resolve: resolve! };
 25	}
 26	
 27	beforeEach(() => {
 28	  vi.resetModules();
 29	  nativeWindow.scaleFactor.mockReset().mockResolvedValue(2);
 30	  nativeWindow.outerPosition.mockReset().mockResolvedValue({ x: 240, y: 480 });
 31	  nativeWindow.setPosition.mockReset().mockResolvedValue(undefined);
 32	  nativeWindow.onMoved.mockReset().mockResolvedValue(() => {});
 33	  nativeWindow.onScaleChanged.mockReset().mockResolvedValue(() => {});
 34	});
 35	
 36	describe("roam window position", () => {
 37	  it("reuses the last native position between movement ticks", async () => {
 38	    const { currentLogicalPos } = await import("./window");
 39	
 40	    await expect(currentLogicalPos()).resolves.toEqual({ x: 120, y: 240 });
 41	    await expect(currentLogicalPos()).resolves.toEqual({ x: 120, y: 240 });
 42	
 43	    expect(nativeWindow.scaleFactor).toHaveBeenCalledTimes(1);
 44	    expect(nativeWindow.outerPosition).toHaveBeenCalledTimes(1);
 45	  });
 46	
 47	  it("updates the cache from native move events", async () => {
 48	    let movedHandler: ((event: { payload: { x: number; y: number } }) => void) | undefined;
 49	    nativeWindow.onMoved.mockImplementation(async (handler) => {
 50	      movedHandler = handler;
 51	      return () => {};
 52	    });
 53	    const { currentLogicalPos } = await import("./window");
 54	
 55	    await currentLogicalPos();
 56	    expect(nativeWindow.onMoved).toHaveBeenCalledTimes(1);
 57	
 58	    movedHandler?.({ payload: { x: 600, y: 360 } });
 59	    await expect(currentLogicalPos()).resolves.toEqual({ x: 300, y: 180 });
 60	    expect(nativeWindow.outerPosition).toHaveBeenCalledTimes(1);
 61	  });
 62	
 63	  it("refreshes the native position after a scale change", async () => {
 64	    let scaleHandler: ((event: { payload: { scaleFactor: number } }) => void) | undefined;
 65	    nativeWindow.onScaleChanged.mockImplementation(async (handler) => {
 66	      scaleHandler = handler;
 67	      return () => {};
 68	    });
 69	    const { currentLogicalPos } = await import("./window");
 70	
 71	    await currentLogicalPos();
 72	    expect(nativeWindow.onScaleChanged).toHaveBeenCalledTimes(1);
 73	
 74	    nativeWindow.scaleFactor.mockResolvedValue(1.5);
 75	    nativeWindow.outerPosition.mockResolvedValue({ x: 300, y: 450 });
 76	    scaleHandler?.({ payload: { scaleFactor: 1.5 } });
 77	
 78	    await expect(currentLogicalPos()).resolves.toEqual({ x: 200, y: 300 });
 79	    expect(nativeWindow.outerPosition).toHaveBeenCalledTimes(2);
 80	  });
 81	
 82	  it("updates the cache after setting a logical position", async () => {
 83	    const { currentLogicalPos, setLogical } = await import("./window");
 84	
 85	    await currentLogicalPos();
 86	    await setLogical({ x: 75, y: 125 });
 87	
 88	    await expect(currentLogicalPos()).resolves.toEqual({ x: 75, y: 125 });
 89	    expect(nativeWindow.outerPosition).toHaveBeenCalledTimes(1);
 90	  });
 91	
 92	  it("does not let a stale read overwrite a newer DPI move event", async () => {
 93	    const scale = deferred<number>();
 94	    const position = deferred<{ x: number; y: number }>();
 95	    let movedHandler: ((event: { payload: { x: number; y: number } }) => void) | undefined;
 96	    let scaleHandler: ((event: { payload: { scaleFactor: number } }) => void) | undefined;
 97	    nativeWindow.scaleFactor.mockImplementationOnce(() => scale.promise);
 98	    nativeWindow.outerPosition.mockImplementationOnce(() => position.promise);
 99	    nativeWindow.onMoved.mockImplementation(async (handler) => {
100	      movedHandler = handler;
101	      return () => {};
102	    });
103	    nativeWindow.onScaleChanged.mockImplementation(async (handler) => {
104	      scaleHandler = handler;
105	      return () => {};
106	    });
107	    const { currentLogicalPos } = await import("./window");
108	
109	    const firstRead = currentLogicalPos();
110	    scale.resolve(1);
111	    await vi.waitFor(() => expect(nativeWindow.outerPosition).toHaveBeenCalledTimes(1));
112	
113	    scaleHandler?.({ payload: { scaleFactor: 1.5 } });
114	    movedHandler?.({ payload: { x: 300, y: 450 } });
115	    position.resolve({ x: 300, y: 450 });
116	
117	    await expect(firstRead).resolves.toEqual({ x: 200, y: 300 });
118	    await expect(currentLogicalPos()).resolves.toEqual({ x: 200, y: 300 });
119	  });
120	
121	  it("retries event tracking after a failed registration", async () => {
122	    const failedRegistration = Promise.reject<() => void>(new Error("listener unavailable"));
