671	                                    wp.x, wp.y
672	                                ));
673	                            }
674	                        }
675	                    }
676	
677	                    // Prune closed windows and persist every instance position,
678	                    // both throttled to roughly once per second.
679	                    tick = tick.wrapping_add(1);
680	                    if tick % 17 == 0 {
681	                        let active: std::collections::HashSet<&String> =
682	                            wins.iter().map(|(label, _)| label).collect();
683	                        if let Some(state) = handle.try_state::<Mutex<HitRectMap>>() {
684	                            if let Ok(mut rects) = state.lock() {
685	                                rects.retain(|label, _| active.contains(label));
686	                            }
687	                        }
688	                        last_ignore.retain(|label, _| active.contains(label));
689	
690	                        let mut changed = false;
691	                        for (label, window) in &wins {
692	                            let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else { continue };
693	                            let Ok(position) = window.outer_position() else { continue };
694	                            let next = (position.x, position.y);
695	                            if last_saved.get(id) != Some(&next) {
696	                                last_saved.insert(id.to_owned(), next);
697	                                changed = true;
698	                            }
699	                        }
700	                        if changed {
701	                            if let Some(state) = handle.try_state::<Mutex<PetPositionMap>>() {
702	                                if let Ok(mut positions) = state.lock() {
703	                                    *positions = last_saved.clone();
704	                                    write_pet_positions(&positions);
705	                                }
706	                            }
707	                        }
708	                    }
709	                }
710	            });

